import os,json,csv,sqlite3,hashlib,zipfile
from pathlib import Path
from collections import Counter
R=Path(r'D:\Clarion');A=R/'research_artifacts';P=A/'processed';
con=sqlite3.connect(f"file:{(R/'Clarion-Backend/data/relation_dataset.db').as_posix()}?mode=ro",uri=True); total,unl=con.execute('select count(*),sum(is_valid is null) from relation_dataset').fetchone();con.close()
q1=json.loads((R/'Clarion-Backend/data/ground_truth/annotation_queue_batch1.json').read_text(encoding='utf-8'));q2=json.loads((R/'Clarion-Backend/data/ground_truth/annotation_queue_batch1_overlap_b.json').read_text(encoding='utf-8')); ov=len({x['record_id'] for x in q1['records']}&{x['record_id'] for x in q2['records']})
(R/'RESEARCH_QUESTION_AND_HYPOTHESIS.md').write_text('''# Research Questions and Hypotheses\n\n| Question and hypothesis | Independent/dependent variables | Baseline, dataset, metrics | Procedure/statistics | Status and limits |\n|---|---|---|---|---|\n| RQ1: tokenizer-aware segmentation prevents over-limit embedding inputs while preserving source chunks. IV: segmenter vs legacy direct input. DV: token-limit violations, span continuity, mapped coverage. | Same input text; input length and segmenter state | Baseline direct BGE input; current readable PDFs; tokens, exact segment spans | Paired same-text run; tokenizer determinism; report every violation | **PARTIALLY VERIFIED**: all 170 current segments <=512; no retrieval effect or independent full-text reference measured. |\n| RQ2: hybrid retrieval improves ranking over sparse and dense alone. IV: BM25/dense/hybrid/rerank. DV: per-query relevance. | Same corpus, frozen queries, labels, model versions | No valid retrieval dataset; P@k, Recall@k, MRR; nDCG only with graded labels | Document-held-out test split, paired query-level comparison, cluster uncertainty by source document | **BLOCKED**: no independent query judgments. |\n| RQ3: graph augmentation increases recall without unacceptable precision loss. IV: graph expansion on/off. DV: evidence retrieval ranking and support. | Same base retriever and query split | None yet; P@k, Recall@k, MRR | Paired test on frozen query set; source document unit | **BLOCKED**: no benchmark. |\n| RQ4: relationship validation reduces unsupported semantic edges. IV: validation/filter threshold. DV: precision, recall, F1, ambiguity. | Same candidate relations and blind human labels | Backend relation DB; precision/recall/F1, kappa on double-labelled overlap | Two independent annotators; adjudication separate; report confusion matrix/class counts | **BLOCKED**: 1,562 candidates, all unlabeled. |\n| RQ5: what is pipeline component cost? IV: component, doc size, cold/warm state. DV: latency, throughput, memory. | Same machine/model/settings | Corpus and repeat runs; median/p95, tokens/sec, throughput | Monotonic clocks, repeated trials, separate warm/cold, per-document analysis | **NOT EVALUATED**: indexing run not instrumented as benchmark. |\n\nThese are testable candidates, not novelty claims or results.\n''',encoding='utf-8')
(R/'RETRIEVAL_EVALUATION_DATASET.md').write_text('''# Retrieval Evaluation Dataset Protocol\n\nNo validated query relevance dataset is present. `research_artifacts/processed/retrieval_queries_template.csv` is header-only. Source PDFs can seed question drafting, but final relevance judgments must be independent of system predictions.\n\nFreeze a source-document-level development/test split before annotation; keep pages and near-duplicate chunks from one source document together. For each query record query ID/text, source document, relevant passage IDs, relevance labels, page/character location, supporting excerpt, assessor ID, timestamp, adjudication, split and run ID. Use two independent assessors for an overlap subset, blinded to system identity and model confidence. Adjudicate disagreements without tuning labels to a kappa target.\n\nEvaluate sparse, dense, hybrid, reranked and graph-augmented approaches on the same frozen corpus, queries and judgments. Record versions, top-k and seeds. For each q: P@k = relevant retrieved/k; Recall@k = relevant retrieved/all relevant; RR(q)=1/rank of first relevant, or 0 if none; MRR=mean RR. Define treatment of queries with zero relevant passages before analysis. Use nDCG only for graded labels. Compare paired query results and cluster uncertainty by source document. No scores or confidence intervals exist yet.\n''',encoding='utf-8')
(R/'ABLATION_STUDY_REPORT.md').write_text(f'''# Ablation Study Report\n\nCurrent canonical backend relation DB: {total} candidates, {unl} unlabeled (read-only query). Root `data/relation_dataset.db` is a separate database and is not mixed into this count. Annotation queues have {q1['total_records']} primary and {q2['total_records']} overlap entries; {ov} record IDs overlap by design. They are queues, not completed human labels.\n\n| Ablation | Single component change | Outcome | Status |\n|---|---|---|---|\n| Full pipeline | No ablation | P@k, Recall@k, MRR, latency | NOT RUN |\n| No graph augmentation | Disable graph expansion only | Ranking/evidence support/cost | NOT RUN |\n| Sparse only | BM25 only | Ranking/latency | NOT RUN |\n| Dense only | Dense only | Ranking/latency | NOT RUN |\n| No reranking | Skip reranker only | Ranking/latency | NOT RUN |\n| No relationship validation | Disable filter only | Human edge precision/recall | BLOCKED: no gold labels |\n\nUse same frozen query set, corpus, versions, top-k and seed, and paired source-document-aware analysis. **Ablations BLOCKED** until valid relevance judgments and human relation labels exist. Synthetic harness results are not empirical quality results.\n''',encoding='utf-8')
(R/'REPOSITORY_CLEANUP_LOG.md').write_text('''# Repository Cleanup Log\n\n## 2026-11-11 — inventory and conservative cache cleanup\n\nCaptured branch/HEAD/status and a tracked diff snapshot under `research_artifacts/2026-11-11_research-validation-presnapshot/` before research outputs were added. Inventoried candidates and temporary directories. Existing package hashes and entry counts appear in `REPOSITORY_CLEANUP_INVENTORY.md`. The worktree already contained extensive user modifications and untracked evidence. Only reproducible local caches and empty temporary directories were moved to quarantine, hash-verified, and removed; production databases, original PDFs, historical evidence, backups, live-provider evidence, and validation environments remain. `.gitignore` was updated to exclude local validation environments and pytest temporary directories for future Git operations. Removed cache file paths, sizes and hashes are recorded in `research_artifacts/processed/cache_cleanup_manifest.csv`; the caches were reproducible and contained no unique source/evidence, so no replacement copy was retained.\n\nExisting ignore rules cover Python bytecode, common virtual environments, pytest/ruff caches, local databases and generated state. This pass added exclusions for the backend validation environments and pytest temporary-output folders. No application source was changed, so backend tests and frontend build were not rerun. Isolated research indexing used its own subdirectory. Cache cleanup candidates, sizes and SHA-256 values are recorded in `research_artifacts/processed/cache_cleanup_manifest.csv`.\n''',encoding='utf-8')
# complete candidate inventory including temporary dirs; exclude .git metadata only
exts={'.zip','.md','.txt','.log','.patch','.diff','.json','.csv','.pdf','.db','.sqlite','.sqlite3'}; items=[];skip={'.git'}
for dp,dns,fns in os.walk(R):
 rel=Path(dp).relative_to(R); dns[:]=[d for d in dns if d not in skip]
 for d in dns:
  if d in {'__pycache__','.pytest_cache','.pytest-tmp','.ruff_cache'} or d.startswith('.venv'):
   items.append({'path':str(rel/d).replace('\\','/'),'size_bytes':'','sha256':'','category':'E. TEMPORARY','rationale':'Cache or local environment; retained, no cleanup.'})
 for n in fns:
  p=Path(dp)/n
  if p.suffix.lower() not in exts and p.name not in {'.gitignore','.env.example'}:continue
  path=str(p.relative_to(R)).replace('\\','/'); size=p.stat().st_size
  parts=Path(path).parts
  if any(part in {'__pycache__','.pytest_cache','.pytest-tmp','.pytest-tmp-live-elevated','.ruff_cache'} or part.startswith('.venv') for part in parts):cat,why='E. TEMPORARY','Cache or local environment candidate; retained, no cleanup.'
  elif path.startswith('docs/') and p.suffix.lower()=='.pdf':cat,why='B. SOURCE MATERIAL','Original PDF source; preserve.'
  elif path.startswith('research_artifacts/'):cat,why='C. REPRODUCIBLE ARTIFACT','Research source, script, result, or chart from validation.'
  elif '/tests/' in path or path.startswith('tests/'):cat,why='A. CANONICAL','Required test/fixture source.'
  elif p.suffix.lower()=='.zip':cat,why='D. HISTORICAL','Existing audit package; hash/entry count inspected; retained.'
  elif path in {'README.md','PROJECT.md','CLARION_CURRENT_STATUS.md','SUBMISSION_READINESS_CHECKLIST.md','FIX_LOG.md','MANUSCRIPT_STATUS_REPORT.md','references.bib','appendix_report.md','.gitignore','Clarion-Backend/.env.example','PDF_SOURCE_REGISTER.md','PDF_RESEARCH_EVIDENCE.md','CHUNKING_FORENSIC_AUDIT.md','CHUNKING_EXPERIMENT_RESULTS.md','RESEARCH_QUESTION_AND_HYPOTHESIS.md','RETRIEVAL_EVALUATION_DATASET.md','ABLATION_STUDY_REPORT.md','REPOSITORY_CLEANUP_INVENTORY.md','REPOSITORY_CLEANUP_LOG.md','RESEARCH_VALIDATION_REPORT.md'}:cat,why='A. CANONICAL','Current project documentation/configuration.'
  elif path.startswith('Clarion-Backend/data/') or path.startswith('data/'):cat,why='B. SOURCE MATERIAL','Database, annotation queue or data; preserved.'
  elif '/reports/' in path or path.endswith('_REPORT.md') or path.endswith('_AUDIT.md') or path.endswith('_LOG.md'):cat,why='D. HISTORICAL','Engineering/research provenance; retained.'
  elif '.pytest' in path or path.startswith('logs/'):cat,why='E. TEMPORARY','Test cache or transient logs; retained pending review.'
  else:cat,why='F. UNKNOWN','Purpose needs review; preserved.'
  h=hashlib.sha256(p.read_bytes()).hexdigest() if p.suffix.lower()=='.zip' or (size<2_000_000 and p.suffix.lower() in {'.csv','.json','.patch','.diff'}) else '(not computed; no removal proposed)'
  items.append({'path':path,'size_bytes':size,'sha256':h,'category':cat,'rationale':why})
with (P/'repository_cleanup_inventory.csv').open('w',newline='',encoding='utf-8-sig') as f:w=csv.DictWriter(f,fieldnames=list(items[0]));w.writeheader();w.writerows(items)
cc=Counter(x['category'] for x in items)
zipinfo=[]
for z in R.glob('*.zip'):
 with zipfile.ZipFile(z) as f: zipinfo.append((z.name,z.stat().st_size,hashlib.sha256(z.read_bytes()).hexdigest(),len(f.namelist()),'; '.join(f.namelist()[:8])))
text='# Repository Cleanup Inventory\n\nInventory date 2026-11-11. Detailed path/size/classification is in `research_artifacts/processed/repository_cleanup_inventory.csv`; `.git` internals omitted. Hashes are included for ZIPs and small evidence files where practical; absent hash means no deletion was proposed. Classification uses project path/content role rather than extension alone.\n\nCounts:\n'+''.join(f'- {k}: {v}\n' for k,v in sorted(cc.items()))+'\nZIP packages (hashes differ; no exact duplicates):\n'
for n,size,h,count,names in zipinfo:text+=f'- `{n}`: {size:,} bytes, SHA-256 `{h}`, {count} entries; initial contents: {names}\n'
text+='\nThe tree contains extensive pre-existing changes and evidence. Original PDFs, snapshots, backups, databases, validation environments, live-provider artifacts, logs, tests and reports remain. Root Python/pytest/ruff caches and two empty backend pytest temp directories were removed after quarantine/hash verification; see `cache_cleanup_manifest.csv`. `.gitignore` excludes local validation environments and pytest temporary directories.\n'
(R/'REPOSITORY_CLEANUP_INVENTORY.md').write_text(text,encoding='utf-8')
print('cleanup rows',len(items),'relation candidates',total,'queues',len(q1['records']),len(q2['records']),'id overlap',ov)




